"""
agents/llm_reasoning/schemas.py
===============================
Pydantic Schemas for Google Gemini Flash Structured Outputs.

Enforces strict schema validation for LLM reasoning and recommended actions.
"""

from typing import Any, Dict, List, Optional
from pydantic import BaseModel, Field, field_validator


class RecommendedActionItem(BaseModel):
    """Structured action recommendation generated by the reasoning layer."""
    action: str = Field(
        description="Policy-compatible action name, e.g. ACTION_RECOMMEND_CONTAINMENT, ACTION_FLAG_ANALYST_REVIEW, ACTION_INCREASE_MONITORING, ACTION_GATHER_EVIDENCE, ACTION_LOG_BASELINE"
    )
    target: str = Field(
        description="Target IP, host, subnet, port, or SOC analyst queue"
    )
    reason: str = Field(
        description="Clear operational rationale explaining why this action is recommended"
    )
    priority: str = Field(
        default="MEDIUM",
        description="Priority of the recommendation: HIGH, MEDIUM, or LOW"
    )
    supporting_evidence: List[str] = Field(
        default_factory=list,
        description="Concrete observed evidence items supporting this recommendation"
    )
    requires_approval: bool = Field(
        default=False,
        description="Whether this action requires human analyst manual approval before execution"
    )

    @field_validator("priority")
    @classmethod
    def validate_priority(cls, v: str) -> str:
        upper = str(v).upper().strip()
        if upper not in ("HIGH", "MEDIUM", "LOW", "CRITICAL"):
            return "MEDIUM"
        return upper


class IncidentReasoningOutput(BaseModel):
    """Complete structured output produced by Google Gemini Flash Reasoning Agent."""
    incident_id: str = Field(
        description="Unique ID of the correlated incident or triggering event"
    )
    summary: str = Field(
        description="Concise, factual executive-level summary of the security event"
    )
    likely_attack: str = Field(
        description="Plausible attack pattern, e.g. Infiltration, DoS / DDoS, Port Scan, Brute Force, or Benign"
    )
    evidence: List[str] = Field(
        default_factory=list,
        description="List of verified, observed evidence items (packet counts, durations, anomalous deviations)"
    )
    mitre_techniques: List[str] = Field(
        default_factory=list,
        description="Applicable MITRE ATT&CK technique IDs (e.g. T1046, T1190, T1071)"
    )
    confidence: float = Field(
        default=0.5,
        description="Calibrated confidence score between 0.0 and 1.0 based solely on provided evidence"
    )
    uncertainties: List[str] = Field(
        default_factory=list,
        description="Key gaps in telemetry, alternative benign explanations, or hypothesis caveats"
    )
    recommended_actions: List[RecommendedActionItem] = Field(
        default_factory=list,
        description="Ordered list of recommended SOC response actions"
    )
    additional_evidence_needed: List[str] = Field(
        default_factory=list,
        description="Telemetry, PCAP traces, or endpoint logs needed to resolve remaining uncertainties"
    )

    @field_validator("confidence", mode="before")
    @classmethod
    def clamp_confidence(cls, v: Any) -> float:
        try:
            val = float(v)
            return max(0.0, min(1.0, val))
        except (ValueError, TypeError):
            return 0.5


class ReasoningReport(BaseModel):
    """Complete reasoning record including execution metadata and status."""
    reasoning_id: str
    incident_id: str
    event_id: Optional[str] = None
    status: str
    model_name: str
    is_mock: bool = False
    output: Optional[IncidentReasoningOutput] = None
    raw_error: Optional[str] = None
    processing_time_s: float = 0.0
    created_at: str
